import React from 'react';
import { CalendarEvent } from '../types';

interface RenderMonitorProps {
  events: CalendarEvent[];
  renderCounts: Record<string, number>;
}

export const RenderMonitor: React.FC<RenderMonitorProps> = ({
  events,
  renderCounts
}) => {
  const totalRenders = Object.values(renderCounts).reduce((acc, c) => acc + c, 0);
  const renderedCount = Object.values(renderCounts).filter((c) => c > 0).length;
  const maxRender = Math.max(...Object.values(renderCounts), 1);

  return (
    <aside className="w-80 bg-[#0b1329] border border-[#1e293b] rounded-xl p-5 flex flex-col text-left">
      <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 mb-4">
        Render Monitor
      </h3>

      <div className="flex items-baseline space-x-6 mb-6">
        <div>
          <div className="text-2xl font-bold text-blue-400 font-mono">
            {totalRenders}
          </div>
          <span className="text-[11px] text-slate-400">total renders logged</span>
        </div>
        <div>
          <div className="text-2xl font-bold text-slate-100 font-mono">
            {renderedCount}/{events.length}
          </div>
          <span className="text-[11px] text-slate-400">cards that have rendered</span>
        </div>
      </div>

      <div className="space-y-3.5 overflow-y-auto max-h-[380px] pr-1">
        {events.map((event) => {
          const count = renderCounts[event.id] || 0;
          const percentage = Math.min((count / maxRender) * 100, 100);

          return (
            <div key={event.id} className="flex items-center text-xs">
              <span className="w-28 text-slate-300 font-medium truncate">
                {event.title}
              </span>
              <div className="flex-1 mx-2 flex items-center">
                <div className="w-full bg-[#131b2e] h-1.5 rounded-full overflow-hidden">
                  <div
                    className="bg-blue-500 h-full rounded-full transition-all duration-300"
                    style={{ width: `${percentage}%` }}
                  />
                </div>
              </div>
              <span className="w-4 text-right font-mono text-slate-400 text-[11px]">
                {count}
              </span>
            </div>
          );
        })}
      </div>
    </aside>
  );
};
